    "language": "JSON SCHEMA",
    "state": "SIGNED TRANSPORT / V1",
    "description": "Defines the JSON safe EIP 712 invocation whose signature binds execution, cost, nonce, chain and settlement route.",
    "content": "{\r\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\r\n  \"$id\": \"https://firmware.dev/schemas/invocation.v1.json\",\r\n  \"title\": \"firmware Signed Invocation\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"invocationId\",\r\n    \"machine\",\r\n    \"chipId\",\r\n    \"artifactDigest\",\r\n    \"input\",\r\n    \"maximumCost\",\r\n    \"deadline\",\r\n    \"nonce\",\r\n    \"revenueRouteDigest\",\r\n    \"chainId\",\r\n    \"verifyingContract\",\r\n    \"signature\"\r\n  ],\r\n  \"properties\": {\r\n    \"invocationId\": { \"$ref\": \"#/$defs/digest\" },\r\n    \"machine\": { \"$ref\": \"#/$defs/address\" },\r\n    \"chipId\": { \"$ref\": \"#/$defs/digest\" },\r\n    \"artifactDigest\": { \"$ref\": \"#/$defs/digest\" },\r\n    \"input\": true,\r\n    \"maximumCost\": { \"$ref\": \"#/$defs/uintString\" },\r\n    \"deadline\": { \"type\": \"integer\", \"minimum\": 0 },\r\n    \"nonce\": { \"type\": \"string\", \"minLength\": 1, \"maxLength\": 128 },\r\n    \"revenueRouteDigest\": { \"$ref\": \"#/$defs/digest\" },\r\n    \"chainId\": { \"type\": \"integer\", \"minimum\": 1 },\r\n    \"verifyingContract\": { \"$ref\": \"#/$defs/address\" },\r\n    \"signature\": {\r\n      \"type\": \"string\",\r\n      \"pattern\": \"^0x[0-9a-fA-F]{130}$\"\r\n    }\r\n  },\r\n  \"$defs\": {\r\n    \"address\": {\r\n      \"type\": \"string\",\r\n      \"pattern\": \"^0x[0-9a-fA-F]{40}$\"\r\n    },\r\n    \"digest\": {\r\n      \"type\": \"string\",\r\n      \"pattern\": \"^0x[0-9a-fA-F]{64}$\"\r\n    },\r\n    \"uintString\": {\r\n      \"type\": \"string\",\r\n      \"pattern\": \"^(0|[1-9][0-9]*)$\"\r\n    }\r\n  }\r\n}"
