  "runtime/executor.ts": {
    "language": "TYPESCRIPT",
    "state": "COMPILED / TESTED",
    "description": "Coordinates verification, atomic state reservation, sandbox execution, rollback and route bound receipt creation.",
    "content": "import type {\r\n  ChipManifest,\r\n  ExecutionReceipt,\r\n  ExecutionStateStore,\r\n  Installation,\r\n  Invocation,\r\n  InvocationAuthorizer,\r\n  Sandbox\r\n} from \"./types.js\";\r\nimport { hashJson, validateInvocation, verifyInstallation } from \"./verifier.js\";\r\n\r\nexport interface ExecutionDependencies {\r\n  sandbox: Sandbox;\r\n  state: ExecutionStateStore;\r\n  authorizer: InvocationAuthorizer;\r\n  now?: () => number;\r\n}\r\n\r\nexport interface ExecutionPackage {\r\n  manifest: ChipManifest;\r\n  artifact: Uint8Array;\r\n  installation: Installation;\r\n}\r\n\r\nexport class ExecutionError extends Error {\r\n  constructor(public readonly code: string) {\r\n    super(code);\r\n    this.name = \"ExecutionError\";\r\n  }\r\n}\r\n\r\nexport async function execute<TInput, TOutput>(\r\n  invocation: Invocation<TInput>,\r\n  installed: ExecutionPackage,\r\n  dependencies: ExecutionDependencies\r\n): Promise<{ output: TOutput; receipt: ExecutionReceipt }> {\r\n  validateInvocation(invocation);\r\n\r\n  const now = dependencies.now ?? Date.now;\r\n  const startedAt = now();\r\n\r\n  if (startedAt >= invocation.deadline) throw new ExecutionError(\"INVOCATION_EXPIRED\");\r\n  if (\r\n    invocation.chipId.toLowerCase() !== installed.installation.chipId.toLowerCase() ||\r\n    invocation.artifactDigest.toLowerCase() !== installed.installation.artifactDigest.toLowerCase()\r\n  ) {\r\n    throw new ExecutionError(\"INSTALLATION_MISMATCH\");\r\n  }\r\n\r\n  if (!await dependencies.authorizer.verify(invocation)) {\r\n    throw new ExecutionError(\"AUTHORIZATION_DENIED\");\r\n  }\r\n\r\n  verifyInstallation(\r\n    installed.manifest,\r\n    installed.artifact,\r\n    installed.installation,\r\n    startedAt\r\n  );\r\n\r\n  const begun = await dependencies.state.begin(\r\n    invocation.machine,\r\n    invocation.nonce,\r\n    invocation.deadline,\r\n    invocation.invocationId,\r\n    invocation.maximumCost\r\n  );\r\n  if (!begun) throw new ExecutionError(\"NONCE_ALREADY_USED\");\r\n\r\n  let finalized = false;\r\n  try {\r\n    const result = await dependencies.sandbox.run(\r\n      installed.artifact,\r\n      installed.manifest.entrypoint,\r\n      invocation.input,\r\n      installed.manifest\r\n    );\r\n\r\n    if (result.meteredCost > invocation.maximumCost) {\r\n      throw new ExecutionError(\"MAXIMUM_COST_EXCEEDED\");\r\n    }\r\n\r\n    const receipt: ExecutionReceipt = {\r\n      receiptVersion: \"1\",\r\n      invocationId: invocation.invocationId,\r\n      machine: invocation.machine,\r\n      chipId: invocation.chipId,\r\n      chipVersion: installed.manifest.version,\r\n      artifactDigest: installed.installation.artifactDigest,\r\n      inputDigest: hashJson(invocation.input),\r\n      outputDigest: hashJson(result.output),\r\n      startedAt,\r\n      completedAt: now(),\r\n      cost: result.meteredCost.toString(),\r\n      routeDigest: invocation.revenueRouteDigest,\r\n      status: \"completed\"\r\n    };\r\n\r\n    await dependencies.state.finalize(\r\n      invocation.invocationId,\r\n      result.meteredCost,\r\n      receipt\r\n    );\r\n    finalized = true;\r\n    return { output: result.output as TOutput, receipt };\r\n  } catch (error) {\r\n    if (!finalized) {\r\n      await dependencies.state.abort(\r\n        invocation.machine,\r\n        invocation.nonce,\r\n        invocation.invocationId\r\n      );\r\n    }\r\n    throw error;\r\n  }\r\n}"
  },
  "runtime/memory.ts": {
    "language": "TYPESCRIPT",
    "state": "COMPILED / TESTED",
    "description": "Provides a Machine scoped atomic execution state store for fast deterministic tests.",
    "content": "import type {\r\n  ExecutionReceipt,\r\n  ExecutionStateStore,\r\n  HexDigest\r\n} from \"./types.js\";\r\nimport { ExecutionError } from \"./executor.js\";\r\n\r\ninterface Account {\r\n  available: bigint;\r\n  spent: bigint;\r\n}\r\n\r\ninterface Reservation {\r\n  machine: string;\r\n  maximumCost: bigint;\r\n}\r\n\r\nexport class MemoryExecutionStore implements ExecutionStateStore {\r\n  private readonly nonces = new Set<string>();\r\n  private readonly reservations = new Map<HexDigest, Reservation>();\r\n  private readonly receipts = new Map<HexDigest, ExecutionReceipt>();\r\n  private readonly accounts = new Map<string, Account>();\r\n\r\n  constructor(initialBalances: Record<string, bigint> = {}) {\r\n    for (const [machine, available] of Object.entries(initialBalances)) {\r\n      this.accounts.set(normalizeMachine(machine), { available, spent: 0n });\r\n    }\r\n  }\r\n\r\n  fund(machine: string, amount: bigint): void {\r\n    if (amount < 0n) throw new ExecutionError(\"INVALID_FUNDING_AMOUNT\");\r\n    const key = normalizeMachine(machine);\r\n    const account = this.accounts.get(key) ?? { available: 0n, spent: 0n };\r\n    account.available += amount;\r\n    this.accounts.set(key, account);\r\n  }\r\n\r\n  async begin(\r\n    machine: string,\r\n    nonce: string,\r\n    _deadline: number,\r\n    invocationId: HexDigest,\r\n    maximumCost: bigint\r\n  ): Promise<boolean> {\r\n    const machineKey = normalizeMachine(machine);\r\n    const nonceKey = machineKey + \":\" + nonce;\r\n    if (this.nonces.has(nonceKey)) return false;\r\n    if (this.reservations.has(invocationId) || this.receipts.has(invocationId)) {\r\n      throw new ExecutionError(\"INVOCATION_ALREADY_EXISTS\");\r\n    }\r\n\r\n    const account = this.accounts.get(machineKey);\r\n    if (maximumCost <= 0n || !account || maximumCost > account.available) {\r\n      throw new ExecutionError(\"BUDGET_EXCEEDED\");\r\n    }\r\n\r\n    account.available -= maximumCost;\r\n    this.nonces.add(nonceKey);\r\n    this.reservations.set(invocationId, { machine: machineKey, maximumCost });\r\n    return true;\r\n  }\r\n\r\n  async finalize(\r\n    invocationId: HexDigest,\r\n    actualCost: bigint,\r\n    receipt: ExecutionReceipt\r\n  ): Promise<void> {\r\n    const reservation = this.reservations.get(invocationId);\r\n    if (!reservation) throw new ExecutionError(\"RESERVATION_NOT_FOUND\");\r\n    if (actualCost < 0n || actualCost > reservation.maximumCost) {\r\n      throw new ExecutionError(\"INVALID_ACTUAL_COST\");\r\n    }\r\n    if (this.receipts.has(invocationId)) {\r\n      throw new ExecutionError(\"RECEIPT_ALREADY_EXISTS\");\r\n    }\r\n\r\n    const account = this.accounts.get(reservation.machine)!;\r\n    account.available += reservation.maximumCost - actualCost;\r\n    account.spent += actualCost;\r\n    this.receipts.set(invocationId, Object.freeze({ ...receipt }));\r\n    this.reservations.delete(invocationId);\r\n  }\r\n\r\n  async abort(machine: string, nonce: string, invocationId: HexDigest): Promise<void> {\r\n    const reservation = this.reservations.get(invocationId);\r\n    if (reservation) {\r\n      const account = this.accounts.get(reservation.machine)!;\r\n      account.available += reservation.maximumCost;\r\n      this.reservations.delete(invocationId);\r\n    }\r\n    this.nonces.delete(normalizeMachine(machine) + \":\" + nonce);\r\n  }\r\n\r\n  balance(machine: string): Readonly<Account> {\r\n    const account = this.accounts.get(normalizeMachine(machine));\r\n    return account ? { ...account } : { available: 0n, spent: 0n };\r\n  }\r\n\r\n  getReceipt(invocationId: HexDigest): ExecutionReceipt | undefined {\r\n    return this.receipts.get(invocationId);\r\n  }\r\n}\r\n\r\nfunction normalizeMachine(machine: string): string {\r\n  return machine.toLowerCase();\r\n}"
  },
